def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    prev_bids = []
    aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                b = prev.get('bid', 0)
                prev_bids.append(b)
                if b >= 60:
                    aggressive += 1

    if budget <= 0:
        return 0.0

    if not alive:
        return float(min(budget, 8.0 if hp > 3 else 18.0))

    units = supply / WATER_REQ
    can_only_feed_one = units < 2.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    urgency = 0
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days >= 1:
        urgency += 1

    if urgency >= 5:
        bid = 68.0
    elif urgency >= 3:
        bid = 52.0 if highest_prev < 60 else highest_prev + 2.0
    else:
        if can_only_feed_one:
            if highest_prev >= 80:
                bid = 18.0
            elif highest_prev >= 55:
                bid = 36.0
            elif highest_prev > 0:
                bid = max(22.0, highest_prev + 1.5)
            else:
                bid = 16.0
        else:
            if aggressive >= 2:
                bid = 28.0
            elif highest_prev >= 60:
                bid = 24.0
            elif avg_prev > 0:
                bid = max(14.0, min(26.0, avg_prev * 0.55 + 4.0))
            else:
                bid = 12.0

    if budget < 25:
        bid = min(bid, budget)
    elif budget < 60 and urgency < 3:
        bid = min(bid, 32.0)

    if hp <= 2 or no_water_days >= 2:
        bid = max(bid, min(0.92 * DAILY_SALARY, budget))

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    n_alive = len(alive_opponents)
    # Urgency
    if my_status['hp'] <= 2:
        return min(my_status['budget'], int(SALARY * 0.95))
    # Supply stress
    supply = day_context['supply']
    stress = (n_alive * WATER_REQ) / supply if supply > 0 else 0
    base = SALARY * 0.5
    if stress > 1.5:
        base = SALARY * 0.7
    # Gather previous bids
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
    if prev_bids:
        highest_prev = max(prev_bids)
        if highest_prev > 100:
            bid = min(my_status['budget'], int(SALARY * 0.3))
        else:
            bid = min(my_status['budget'], int(max(base, highest_prev + 2)))
    else:
        bid = min(my_status['budget'], int(base))
    return max(0, bid)
